import random
import struct
from typing import List

# Generator for raw audio buffers targeting oboe::AudioStream::write with numFrames=1.
# Produces valid, interesting single-frame payloads across PCM formats and channel counts,
# plus compressed 1-byte-per-frame cases. Ensures at least 16 bytes and <=4096 bytes.

# Pack helpers

def _pack_i16(samples: List[int]) -> bytes:
    # values must be within int16
    clamped = [max(-32768, min(32767, int(v))) for v in samples]
    return struct.pack('<' + 'h'*len(clamped), *clamped)


def _pack_i24(samples: List[int]) -> bytes:
    # 24-bit packed little-endian
    out = bytearray()
    for v in samples:
        v = int(v)
        if v > 0x7FFFFF:
            v = 0x7FFFFF
        if v < -0x800000:
            v = -0x800000
        if v < 0:
            v = (1 << 24) + v
        out.append(v & 0xFF)
        out.append((v >> 8) & 0xFF)
        out.append((v >> 16) & 0xFF)
    return bytes(out)


def _pack_i32(samples: List[int]) -> bytes:
    # clamp to int32 range to avoid struct.error
    clamped = [max(-0x80000000, min(0x7FFFFFFF, int(v))) for v in samples]
    return struct.pack('<' + 'i'*len(clamped), *clamped)


def _pack_f32(samples: List[float]) -> bytes:
    # limit to finite range [-1,1] typical for audio
    bounded = [float(max(-1.0, min(1.0, v))) for v in samples]
    return struct.pack('<' + 'f'*len(bounded), *bounded)

_CHANNEL_OPTIONS = [1, 2, 3, 4, 6, 8]

# Base patterns

def _base_pcm_i16(ch: int) -> List[List[int]]:
    vals = [0, 32767, -32768, 16384, -16384, 8192, -8192, 12345, -23456]
    return [
        [0]*ch,
        [32767]*ch,
        [-32768]*ch,
        [vals[i % len(vals)] for i in range(ch)],
        [20000 if (i % 2 == 0) else -20000 for i in range(ch)],
    ]


def _base_pcm_i24(ch: int) -> List[List[int]]:
    return [
        [0]*ch,
        [0x7FFFFF]*ch,
        [-0x800000]*ch,
        [300000 if (i % 2 == 0) else -300000 for i in range(ch)],
    ]


def _base_pcm_i32(ch: int) -> List[List[int]]:
    base = [0, 1<<28, -(1<<28), 1<<24, -(1<<24), 123456789, -98765432]
    return [
        [0]*ch,
        [0x7FFFFFFF]*ch,
        [-0x80000000]*ch,
        [base[i % len(base)] for i in range(ch)],
    ]


def _base_pcm_f32(ch: int) -> List[List[float]]:
    return [
        [0.0]*ch,
        [1.0]*ch,
        [-1.0]*ch,
        [0.75 if (i % 2 == 0) else -0.75 for i in range(ch)],
        [1e-6 if (i % 2 == 0) else -1e-6 for i in range(ch)],
    ]

_COMPRESSED_TOKENS = [b'\x00', b'\xFF', b'\x7F', b'\x01', b'\xAA', b'\x55']

# Procedural variation within valid ranges

def _vary_i16(rnd: random.Random, ch: int) -> List[int]:
    base = rnd.randrange(-30000, 30001)
    step = rnd.randrange(-4000, 4001)
    seq = []
    for i in range(ch):
        v = base + i * step
        # wrap into int16 range
        if v > 32767:
            v = 32767 - (v - 32767) % 65536
        if v < -32768:
            v = -32768 + (-32768 - v) % 65536
        seq.append(int(v))
    return seq


def _vary_i24(rnd: random.Random, ch: int) -> List[int]:
    base = rnd.randrange(-0x7FFFFF, 0x7FFFFF + 1)
    step = rnd.randrange(-200000, 200001)
    return [max(-0x800000, min(0x7FFFFF, base + i*step)) for i in range(ch)]


def _vary_i32(rnd: random.Random, ch: int) -> List[int]:
    base = rnd.randrange(-0x7FFFFFFF, 0x7FFFFFFF)
    step = rnd.randrange(-(1<<27), (1<<27))
    seq = [base + i*step for i in range(ch)]
    # clamp to int32
    return [max(-0x80000000, min(0x7FFFFFFF, v)) for v in seq]


def _vary_f32(rnd: random.Random, ch: int) -> List[float]:
    base = rnd.uniform(-1.0, 1.0)
    step = rnd.uniform(-0.9, 0.9)
    seq = []
    for i in range(ch):
        v = base + i * step
        # wrap into [-1,1]
        while v > 1.0:
            v -= 2.0
        while v < -1.0:
            v += 2.0
        seq.append(float(v))
    return seq


def _catalog_entries() -> List[bytes]:
    out: List[bytes] = []
    for ch in _CHANNEL_OPTIONS:
        for p in _base_pcm_i16(ch):
            out.append(_pack_i16(p))
        for p in _base_pcm_i24(ch):
            out.append(_pack_i24(p))
        for p in _base_pcm_i32(ch):
            out.append(_pack_i32(p))
        for p in _base_pcm_f32(ch):
            out.append(_pack_f32(p))
    out.extend(_COMPRESSED_TOKENS)
    if len(out) >= 3:
        out.append((out[0] + out[1] + out[2])[:64])
    return [e[:4096] for e in out]

_CATALOG = _catalog_entries()


def _ensure_min_len(b: bytes, minimum: int = 16) -> bytes:
    if len(b) >= minimum:
        return b
    if len(b) == 0:
        return bytes([0]*minimum)
    reps = (minimum + len(b) - 1) // len(b)
    return (b * reps)[:minimum]


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)

    mode = rnd.choice(['catalog', 'i16', 'i24', 'i32', 'f32', 'compressed'])

    if mode == 'catalog':
        buf = _CATALOG[rnd.randrange(len(_CATALOG))]
    elif mode == 'compressed':
        # Build a short token sequence; valid for bytesPerFrame==1. Extra bytes are fine.
        length = rnd.randint(16, 96)
        token = rnd.choice(_COMPRESSED_TOKENS)
        buf = (token * ((length + len(token) - 1)//len(token)))[:length]
    else:
        ch = rnd.choice(_CHANNEL_OPTIONS)
        if mode == 'i16':
            samples = _vary_i16(rnd, ch) if rnd.random() < 0.6 else random.choice(_base_pcm_i16(ch))
            buf = _pack_i16(samples)
        elif mode == 'i24':
            samples = _vary_i24(rnd, ch) if rnd.random() < 0.6 else random.choice(_base_pcm_i24(ch))
            buf = _pack_i24(samples)
        elif mode == 'i32':
            samples = _vary_i32(rnd, ch) if rnd.random() < 0.6 else random.choice(_base_pcm_i32(ch))
            buf = _pack_i32(samples)
        elif mode == 'f32':
            samples = _vary_f32(rnd, ch) if rnd.random() < 0.6 else random.choice(_base_pcm_f32(ch))
            buf = _pack_f32(samples)
        else:
            buf = b''

    buf = _ensure_min_len(buf, 16)

    # Occasionally duplicate to vary size while staying valid
    if rnd.random() < 0.4 and len(buf) < 256:
        buf = (buf + buf)[:256]

    return buf[:4096]
